import { makeExpression } from 'app/services/MelodiesService/expression';

type Point = { time: number; cents: number };
type Gesture = { midi: number; points: Point[] };

/** Follow a measured solo fundamental before rounding it to a note. Histories
 * survive a handover so the old voice's final event keeps its pitch curve. */
export const createLiveExpression = () => {
  let active: Gesture | undefined;
  let previous: { midi: number; time: number } | undefined;
  let lastRootTime = -Infinity;
  let step: { midi: number; since: number; boundary: number } | undefined;
  let expressive = false;
  const history: Gesture[] = [];
  const reset = () => {
    active = undefined;
    previous = undefined;
    step = undefined;
    expressive = false;
  };
  const curve = (midi: number, start: number, end: number) => {
    const gesture = history
      .filter(
        item =>
          item.midi === midi &&
          item.points[0].time < end &&
          item.points[item.points.length - 1].time >= start,
      )
      .sort((a, b) => {
        const overlap = (item: Gesture) =>
          Math.min(end, item.points[item.points.length - 1].time) -
          Math.max(start, item.points[0].time);
        return overlap(b) - overlap(a);
      })[0];
    if (!gesture || end <= start) return;
    const first =
      gesture.points.filter(point => point.time <= start).slice(-1)[0] ??
      gesture.points[0];
    const points = [
      { position: 0, cents: first.cents },
      ...gesture.points
        .filter(point => point.time > start && point.time < end)
        .map(point => ({
          position: (point.time - start) / (end - start),
          cents: point.cents,
        })),
    ];
    const last = points[points.length - 1].cents;
    const low = points.reduce((value, p) => Math.min(value, p.cents), Infinity);
    const high = points.reduce(
      (value, p) => Math.max(value, p.cents),
      -Infinity,
    );
    const expression =
      end - start >= 80 && high - low >= 40
        ? makeExpression(points)
        : undefined;
    if (gesture === active) expressive = !!expression?.techniques.length;
    return {
      cents: last,
      expression: expression?.techniques.length ? expression : undefined,
    };
  };
  return {
    reset,
    get reference() {
      return expressive && previous
        ? 440 * 2 ** ((previous.midi - 69) / 12)
        : undefined;
    },
    observe(
      frequency: number,
      time: number,
      attack = -Infinity,
      locked = true,
    ) {
      const midi = 69 + 12 * Math.log2(frequency / 440);
      const jump = previous ? Math.abs(midi - previous.midi) : Infinity;
      const quantizedStep =
        previous &&
        Math.round(midi) !== Math.round(previous.midi) &&
        jump > 0.45 &&
        Math.abs(midi - Math.round(midi)) < 0.12 &&
        Math.abs(previous.midi - Math.round(previous.midi)) < 0.12;
      if (active && Math.abs(midi - active.midi) < 0.12) lastRootTime = time;
      if (step && Math.abs(midi - step.midi) > 0.08) step = undefined;
      if (
        active &&
        !step &&
        Math.abs(midi - active.midi) >= 0.8 &&
        time - lastRootTime <= 80 &&
        Math.abs(midi - Math.round(midi)) < 0.08
      )
        step = { midi: Math.round(midi), since: time, boundary: lastRootTime };
      const settledStep = step && time - step.since >= 45;
      if (settledStep && active)
        active.points = active.points.filter(
          point => point.time <= step!.boundary,
        );
      if (
        !active ||
        !previous ||
        (!locked && active.midi !== Math.round(midi)) ||
        time - previous.time > 80 ||
        jump > Math.max(0.65, (time - previous.time) * 0.04) ||
        quantizedStep ||
        settledStep ||
        attack > active.points[0].time + 160
      ) {
        active = { midi: Math.round(midi), points: [] };
        history.push(active);
        if (history.length > 4) history.shift();
        step = undefined;
        expressive = false;
        lastRootTime = time;
      }
      const point = { time, cents: (midi - active.midi) * 100 };
      const points = active.points;
      const before = points[points.length - 2],
        last = points[points.length - 1];
      // Collapse a straight or stationary section, preserving bends and
      // vibrato extrema to within two cents. Cost stays bounded for long holds.
      if (
        before &&
        last &&
        point.time - before.time <= 50 &&
        Math.abs(point.cents - before.cents) < 10 &&
        Math.abs(last.cents - before.cents) > 35
      ) {
        // A pick transient can briefly move YIN by almost a semitone. Its
        // immediate return is not a bend or sustained vibrato.
        points.pop();
      } else if (before && last && point.time - before.time <= 80) {
        const expected =
          before.cents +
          ((point.cents - before.cents) * (last.time - before.time)) /
            (point.time - before.time);
        if (Math.abs(last.cents - expected) < 2) points.pop();
      }
      points.push(point);
      previous = { midi, time };
      return active.midi;
    },
    curve,
  };
};
