import { tuningLabel } from '../SettingsService/microtonal';
import { NoteExpression, NoteTechnique, PitchPoint } from './types';

export const techniqueNames: Record<NoteTechnique, string> = {
  bend: 'Bend',
  slide: 'Slide',
  vibrato: 'Vibrato',
  'wide-vibrato': 'Wide vibrato',
};

export const expressionLabel = (expression?: NoteExpression) => {
  if (
    expression?.points.length &&
    !expression.techniques.length &&
    expression.points.every(p => p.cents === expression.points[0].cents)
  )
    return `Tuning: ${tuningLabel(expression.points[0].cents)}`;
  return (
    expression?.techniques.map(kind => techniqueNames[kind]).join(', ') ?? ''
  );
};

export const pitchAt = (points: PitchPoint[], position: number) => {
  if (!points.length) return 0;
  let previous = points[0];
  for (const next of points) {
    if (next.position > position) {
      const ratio = Math.max(
        0,
        (position - previous.position) / (next.position - previous.position),
      );
      return previous.cents + (next.cents - previous.cents) * ratio;
    }
    previous = next;
  }
  return previous.cents;
};

/** Generic pitch automation cannot prove the physical playing technique.
 * Use repeated reversals for vibrato and a >=3-semitone sweep for slides.
 * Explicit Guitar Pro markings override this inference. */
export const inferTechniques = (points: PitchPoint[]): NoteTechnique[] => {
  if (!points.length) return [];
  let anchor = points[0].cents;
  let direction = 0;
  let reversals = 0;
  const extrema = [anchor];
  points.forEach(point => {
    const delta = point.cents - anchor;
    if (Math.abs(delta) < 18) return;
    const next = Math.sign(delta);
    if (direction && next !== direction) {
      reversals++;
      extrema.push(anchor);
    }
    direction = next;
    anchor = point.cents;
  });
  extrema.push(anchor);
  const swings = extrema
    .slice(1)
    .map((value, i) => Math.abs(value - extrema[i]));
  swings.sort((a, b) => a - b);
  const span =
    Math.max(...points.map(p => p.cents)) -
    Math.min(...points.map(p => p.cents));
  const kinds: NoteTechnique[] = [];
  if (reversals >= 3) {
    kinds.push(
      swings[Math.floor(swings.length / 2)] >= 80 ? 'wide-vibrato' : 'vibrato',
    );
    if (Math.abs(points[points.length - 1].cents - points[0].cents) > 120)
      kinds.unshift(span >= 300 ? 'slide' : 'bend');
  } else if (span >= 40 || Math.abs(points[0].cents) >= 40) {
    kinds.push(span >= 300 ? 'slide' : 'bend');
  }
  return kinds;
};

export const makeExpression = (
  input: PitchPoint[],
  techniques?: NoteTechnique[],
): NoteExpression | undefined => {
  const points: PitchPoint[] = [];
  input
    .filter(p => Number.isFinite(p.position) && Number.isFinite(p.cents))
    .map(p => ({
      position: Math.max(0, Math.min(1, p.position)),
      cents: Math.max(-9600, Math.min(9600, p.cents)),
    }))
    .sort((a, b) => a.position - b.position)
    .forEach(p => {
      if (points[points.length - 1]?.position === p.position) points.pop();
      points.push(p);
    });
  if (!points.length || points.every(p => Math.abs(p.cents) < 2))
    return undefined;
  if (points[0].position > 0) points.unshift({ ...points[0], position: 0 });
  if (points[points.length - 1].position < 1)
    points.push({ ...points[points.length - 1], position: 1 });
  return {
    points,
    techniques: techniques?.length
      ? Array.from(new Set(techniques))
      : inferTechniques(points),
  };
};

/** Crop a sounding note without restarting its bend/vibrato phase. */
export const cropExpression = (
  expression: NoteExpression | undefined,
  from: number,
  to = 1,
): NoteExpression | undefined => {
  if (!expression || from >= to) return undefined;
  return {
    ...expression,
    points: [
      { position: 0, cents: pitchAt(expression.points, from) },
      ...expression.points
        .filter(p => p.position > from && p.position < to)
        .map(p => ({ ...p, position: (p.position - from) / (to - from) })),
      { position: 1, cents: pitchAt(expression.points, to) },
    ],
  };
};

export const scheduleExpression = (
  param: AudioParam,
  expression: NoteExpression,
  start: number,
  duration: number,
) => {
  expression.points.forEach((point, index) => {
    const at = start + point.position * duration;
    if (!index) param.setValueAtTime(point.cents, at);
    else param.linearRampToValueAtTime(point.cents, at);
  });
};
